+    #[test]
+    fn git_exclude_linked_worktree_without_require_git() {
+        let td = tmpdir();
+        let git_dir = td.path().join("shared/.git");
+        let worktree_git_dir = git_dir.join("worktrees/linked");
+        mkdirp(git_dir.join("info"));
+        mkdirp(&worktree_git_dir);
+        wfile(git_dir.join("info/exclude"), "/ignored\n");
+        let root = td.path().join("worktrees");
+        let worktree = root.join("linked");
+        mkdirp(&worktree);
+        wfile(
+            worktree.join(".git"),
+            &format!("gitdir: {}\n", worktree_git_dir.display()),
+        );
+        wfile(worktree.join("ignored"), "");
+        wfile(worktree.join("kept"), "");
+
+        for commondir in ["../..".to_string(), git_dir.display().to_string()] {
+            wfile(worktree_git_dir.join("commondir"), &commondir);
+            for start in [&root, &worktree] {
+                let mut builder = WalkBuilder::new(start);
+                builder.require_git(false).git_global(false).parents(false);
+                let expected = if start == &root {
+                    vec!["linked", "linked/kept"]
+                } else {
+                    vec!["kept"]
+                };
+                assert_paths(start, &builder, &expected);
+
+                builder.git_exclude(false);
+                let expected = if start == &root {
+                    vec!["linked", "linked/ignored", "linked/kept"]
+                } else {
+                    vec!["ignored", "kept"]
+                };
+                assert_paths(start, &builder, &expected);
+            }
+        }
+    }
