 	}
 	return FileMode(mode), nil
@@ -142,6 +146,28 @@ func (m FileMode) Bytes() []byte {
 	return ret
 }

+// Canonical returns the mode Git uses when reading a tree entry. Regular
+// files use only the owner's execute bit to select Regular or Executable;
+// directory and symlink permissions are discarded. All other types,
+// including unrecognized ones, become Submodule.
+//
+// This does not change the receiver or validate its original value.
+func (m FileMode) Canonical() FileMode {
+	switch m & 0o170000 {
+	case 0o040000:
+		return Dir
+	case 0o100000:
+		if m&0o100 != 0 {
+			return Executable
+		}
+		return Regular
+	case 0o120000:
+		return Symlink
+	default:
+		return Submodule
+	}
+}
+
